import { Spec } from '../core/proto/common.js';
import { DeepWoundsMechanism } from '../core/proto/warrior.js';
import { EventID } from '../core/typed_event.js';
import { Player } from '../core/player.js';

import * as InputHelpers from '../core/components/input_helpers.js';

// Tunables for the experimental Deep Wounds munch/vomit model, shared by DPS and Protection warrior.
// They live in SpecOptions.deepWoundsMechanism and only show while "Enable DW Munch/Vomit" is checked (the default).
// Millisecond fields: 0 in the proto = built-in default (so old saved settings keep today's behavior);
// a typed 0 is stored as -1 so it stays distinguishable from "unset".

type DWSpec = Spec.SpecWarrior | Spec.SpecProtectionWarrior;

// Display copy of the sim's defaults (dwDefault* in sim/warrior/deep_wounds.go) -- keep the two in sync.
// The sim uses its own values whenever a field is left at 0; these only decide what the box shows.
const DW_DEFAULTS = {
	delayMomentMs: 150,
	batchPeriodMs: 200,
	batchDriftMs: 10,
};

function getMechanism<SpecType extends DWSpec>(player: Player<SpecType>): DeepWoundsMechanism {
	return (player.getSpecOptions() as any).deepWoundsMechanism || DeepWoundsMechanism.create();
}

function setMechanism<SpecType extends DWSpec>(eventID: EventID, player: Player<SpecType>, update: Partial<DeepWoundsMechanism>) {
	const options = player.getSpecOptions() as any;
	options.deepWoundsMechanism = DeepWoundsMechanism.create({ ...getMechanism(player), ...update });
	player.setSpecOptions(eventID, options);
}

const modelOn = <SpecType extends DWSpec>(player: Player<SpecType>) => !(player.getSpecOptions() as any).disableDeepWoundsMunchVomit;

function msInput<SpecType extends DWSpec>(field: keyof typeof DW_DEFAULTS, label: string, tooltip: string, showWhen: (player: Player<SpecType>) => boolean) {
	return InputHelpers.makeSpecOptionsNumberInput<SpecType>({
		fieldName: 'deepWoundsMechanism' as any,
		label: label,
		labelTooltip: `${tooltip} Default: ${DW_DEFAULTS[field]} ms.`,
		showWhen: showWhen,
		getValue: (player: Player<SpecType>) => {
			const v = getMechanism(player)[field];
			return v === 0 ? DW_DEFAULTS[field] : Math.max(v, 0);
		},
		setValue: (eventID: EventID, player: Player<SpecType>, newVal: number) => {
			const v = Math.max(Math.round(newVal), 0);
			setMechanism(eventID, player, { [field]: v === DW_DEFAULTS[field] ? 0 : v === 0 ? -1 : v });
		},
	});
}

export function makeDeepWoundsMechanismInputs<SpecType extends DWSpec>() {
	return [
		msInput<SpecType>('delayMomentMs', 'DW: DelayMoment (ms)',
			'server delay between the bank READ (after the batch) and the WRITE.', modelOn),
		msInput<SpecType>('batchPeriodMs', 'DW: Batch Window (ms)',
			'Window of the server batch that proc effects wait for.', modelOn),
		msInput<SpecType>('batchDriftMs', 'DW: Map Update (ms)',
			"Length variation of each batch", modelOn),
	];
}
